DO $$
BEGIN
    IF to_regclass('promo.coupon_codes') IS NOT NULL AND to_regclass('promo.pricing_rules') IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM pg_constraint c
        JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey)
        WHERE c.conrelid = to_regclass('promo.coupon_codes') AND c.contype = 'f' AND a.attname = 'pricing_rule_id'
    ) THEN
        ALTER TABLE promo.coupon_codes ADD CONSTRAINT fk_coupon_codes_pricing_rule_id FOREIGN KEY (pricing_rule_id) REFERENCES promo.pricing_rules (id) NOT VALID;
        BEGIN
            ALTER TABLE promo.coupon_codes VALIDATE CONSTRAINT fk_coupon_codes_pricing_rule_id;
        EXCEPTION WHEN foreign_key_violation THEN
            RAISE NOTICE 'fk_coupon_codes_pricing_rule_id left NOT VALID: stored rows of promo.coupon_codes reference missing rows';
        END;
    END IF;
END $$;

